def shared_settings(c=None):
    if c is None:
        with reading() as cx:return shared_settings(cx)
    try: value=json.loads(meta(c,'shared_settings','{}'))
    except ValueError:value={}
    return {**DEFAULT_SETTINGS,**{k:str(v) for k,v in value.items() if k in DEFAULT_SETTINGS}}


def save_shared_settings(data):
    value={k:text(data.get(k,DEFAULT_SETTINGS[k]),1000 if k=='receipt_note' else 200) for k in DEFAULT_SETTINGS}
    if not value['company'] or not value['department']:raise AppError('Escribe el nombre de la empresa y del departamento.')
    with transaction() as c:put_meta(c,'shared_settings',json.dumps(value,ensure_ascii=False));bump(c)
    return {'saved':True}










def rows(c, sql, args=()): return [dict(r) for r in c.execute(sql,args).fetchall()]
def meta(c,key,default=''):
    r=c.execute('SELECT value FROM meta WHERE key=?',(key,)).fetchone()
    return r['value'] if r else default

def put_meta(c,key,value):
    c.execute('INSERT INTO meta(key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',(key,str(value)))

def bump(c): put_meta(c,'revision',int(meta(c,'revision','0'))+1)

def qty(c,pid):
    return c.execute('SELECT COALESCE(SUM(delta),0) FROM lines WHERE product_id=?',(pid,)).fetchone()[0]


