CATALOG_REVIEW_SOURCE = 'INVENTARIOS MARCAS30-10 (2).xlsx'
CATALOG_REVIEW_VERSION = '2026-11-02-v15'


def seed_catalog():
    return json.loads(zlib.decompress(base64.b64decode(SEED_B64)))


def reconcile_catalog(c):
    """Add missing identities only. Existing quantities/codes/history are untouched.

    On an existing database, even a missing article with a positive source balance
    is restored at zero. Its quantity must be verified by a real receipt/count.
    This prevents historical stock from being injected a second time.
    """
    products=rows(c,"SELECT p.*,b.name AS brand FROM products p JOIN brands b ON b.id=p.brand_id")
    existing={(norm(p['brand']),norm(p['name'])):p for p in products}
    codes={p['code']:p for p in products}
    seq=max([int(m.group(1)) for p in products if (m:=re.fullmatch(r'MKT-(\d+)',p['code']))]+[0])
    added=[];conflicts=[]
    for item in seed_catalog():
        identity=(norm(item['brand']),norm(item['name']))
        if identity in existing:continue
        collision=codes.get(item['code'])
        if collision and norm(collision['brand'])==identity[0] and collision.get('source')==item['source']:
            conflicts.append({'expected_code':item['code'],'brand':item['brand'],'name':item['name'],
                              'existing_code':collision['code'],'existing_name':collision['name'],
                              'reason':'Descripción editada: se conserva sin duplicarla.'})
            continue
        c.execute('INSERT OR IGNORE INTO brands(name,normalized) VALUES (?,?)',(item['brand'],identity[0]))
        bid=c.execute('SELECT id FROM brands WHERE normalized=?',(identity[0],)).fetchone()[0]
        code=item['code']
        if code in codes:
            seq+=1;code=f'MKT-{seq:04}'
            while code in codes:seq+=1;code=f'MKT-{seq:04}'
        else:
            match=re.fullmatch(r'MKT-(\d+)',code)
            if match:seq=max(seq,int(match.group(1)))
        note=('Referencia recuperada del catálogo verificado; alta en cero, sin reponer existencias históricas. '
              f"Saldo del archivo de apertura: {item['qty']}. Revisar cantidad antes de registrar una entrada real.")
        pid=c.execute("INSERT INTO products(code,brand_id,name,normalized,source,note,created_day) VALUES (?,?,?,?,?,?,?)",(code,bid,item['name'],identity[1],item['source'],note,today().isoformat())).lastrowid
        rec={'id':pid,'code':code,'brand':item['brand'],'name':item['name'],'source':item['source']}
        existing[identity]=rec;codes[code]=rec
        added.append({'code':code,'brand':item['brand'],'name':item['name'],'source_quantity':item['qty'],'stock_added':0})
    if added:
        try:log=json.loads(meta(c,'catalog_repair_log','[]'))
        except ValueError:log=[]
        log.append({'at':now_iso(),'version':CATALOG_REVIEW_VERSION,'added':added})
        put_meta(c,'catalog_repair_log',json.dumps(log,ensure_ascii=False));bump(c)
    put_meta(c,'catalog_review_version',CATALOG_REVIEW_VERSION)
    put_meta(c,'catalog_conflicts',json.dumps(conflicts,ensure_ascii=False))
    return {'added':added,'conflicts':conflicts,'stock_changed':False}


def catalog_check(c,products=None):
    products=product_list(c) if products is None else products
    bykey={(norm(p['brand']),norm(p['name'])):p for p in products}
    expected=seed_catalog(); brands={};missing=[]
    for e in expected:
        b=brands.setdefault(e['brand'],{'brand':e['brand'],'expected':0,'found':0,'stock':0,'zero':0})
        b['expected']+=1;p=bykey.get((norm(e['brand']),norm(e['name'])))
        if p:
            b['found']+=1;b['stock']+=p['stock'];b['zero']+=int(p['stock']==0)
        else:missing.append({'brand':e['brand'],'name':e['name'],'code':e['code']})
    try:repairs=json.loads(meta(c,'catalog_repair_log','[]'))
    except ValueError:repairs=[]
    try:conflicts=json.loads(meta(c,'catalog_conflicts','[]'))
    except ValueError:conflicts=[]
    return {'source':CATALOG_REVIEW_SOURCE,'expected':len(expected),'matched':len(expected)-len(missing),
            'brands':sorted(brands.values(),key=lambda x:x['brand']),'missing':missing,
            'repairs':repairs,'conflicts':conflicts,'additional':len(products)-(len(expected)-len(missing))}


def repair_catalog(data):
    with transaction() as c:
        result=reconcile_catalog(c);result['check']=catalog_check(c)
    return result


def catalog_csv():
    with reading() as c:products=product_list(c)
    current={(norm(p['brand']),norm(p['name'])):p for p in products}
    stream=io.StringIO();writer=csv.writer(stream,delimiter=';')
    writer.writerow(['Código actual','Marca','Artículo esperado','Estado de catálogo','Existencia actual',
                     'Cantidad de apertura de referencia (no se recarga)','Origen en Excel'])
    for p in seed_catalog():
        found=current.get((norm(p['brand']),norm(p['name'])))
        writer.writerow([found['code'] if found else '',p['brand'],p['name'],'PRESENTE' if found else 'REVISAR',
                         found['stock'] if found else '',p['qty'],p['source']])
    return ('\ufeff'+stream.getvalue()).encode('utf-8')



