def pdf_logo(logo,Image):
    if not logo:return []
    from reportlab.lib.utils import ImageReader
    w,h=ImageReader(io.BytesIO(logo)).getSize();scale=min(130/w,45/h)
    return [Image(io.BytesIO(logo),width=w*scale,height=h*scale,hAlign='LEFT')]

def receipt_pdf(d):
    """Branded, paginated printable receipt. No simulated or generated signatures."""
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, KeepTogether
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.utils import ImageReader
    cfg=shared_settings();logo=get_logo();ink=colors.HexColor('#252329');red=colors.HexColor('#811b23')
    pale=colors.HexColor('#f6f2f3');gray=colors.HexColor('#756e74');line=colors.HexColor('#e5dce0')
    width=A4[0]-72
    style=ParagraphStyle('receipt_cell',fontName='Helvetica',fontSize=9,leading=13,textColor=ink)
    bold=ParagraphStyle('receipt_bold',parent=style,fontName='Helvetica-Bold')
    small=ParagraphStyle('receipt_small',parent=style,fontSize=8,leading=11,textColor=gray)
    head=ParagraphStyle('receipt_head',parent=style,fontName='Helvetica-Bold',textColor=colors.white,fontSize=8)
