    P=lambda value,s=style:Paragraph(html.escape(str(value)).replace('\n','<br/>'),s)
    date_label=datetime.strptime(d['day'],'%Y-%m-%d').strftime('%d/%m/%Y')
    heading='CONSTANCIA DE ENTREGA' if d['kind']=='ENTREGA' else KINDS[d['kind']].upper()
    is_test=d['kind']=='PRUEBA'
    valid=not d['reversed_by']; status='ANULADA' if not valid else 'REGISTRADA · FIRMA EN PAPEL'
    if is_test:
        heading='PEDIDO DE PRUEBA'
        status='NO DESCUENTA NI RESERVA INVENTARIO · NO ES UNA ENTREGA REAL'
    def page_frame(canvas,doc):
        canvas.saveState();w,h=A4
        canvas.setFillColor(red);canvas.rect(0,h-8,w,8,stroke=0,fill=1)
        if logo:
            image=ImageReader(io.BytesIO(logo));iw,ih=image.getSize();scale=min(235/iw,45/ih)
            canvas.drawImage(image,36,h-73,width=iw*scale,height=ih*scale,mask='auto')
        canvas.setFont('Helvetica-Bold',9);canvas.setFillColor(ink);canvas.drawRightString(w-36,h-40,d['number'])
        canvas.setFont('Helvetica',8);canvas.setFillColor(gray);canvas.drawRightString(w-36,h-55,date_label)
        canvas.setStrokeColor(line);canvas.line(36,h-93,w-36,h-93)
