        if is_test:
            canvas.setFillColor(red);canvas.setFont('Helvetica-Bold',8)
            canvas.drawCentredString(w/2,h-87,'PRUEBA / SIN VALIDEZ DE ENTREGA / SIN DESCUENTO')
