def seller_rows_from_month(r):
    """Use the month ledger (also frozen closings), not the 400-record UI list."""
    with reading() as c:
        status={x['id']:x for x in rows(c,'''SELECT d.id,d.reversed_by,rev.day AS annulled_day,
            (SELECT COUNT(*) FROM attachments a WHERE a.document_id=d.id) AS attached
            FROM documents d LEFT JOIN documents rev ON rev.id=d.reversed_by WHERE d.kind='ENTREGA' AND d.day BETWEEN ? AND ?''',(r['start'],r['end']))}
    data=[]
    for m in r['movements']:
        if m['kind']!='ENTREGA':continue
        doc=status.get(m['document_id'],{})
        annulled=bool(doc.get('annulled_day') and doc['annulled_day']<=r['end'])
        data.append({'day':m['day'],'number':m['number'],'document_id':m['document_id'],
            'recipient':m['recipient'],'brand':m['brand'],'code':m['code'],'name':m['name'],
            'quantity':m['quantity'],'effective':0 if annulled else m['quantity'],
            'status':'ANULADA' if annulled else 'VIGENTE','operator':m['operator'],
            'signature':'Adjunto recibido; firma no verificada' if doc.get('attached') else 'Pendiente de adjuntar',
            'note':m['note']})
    return data


def seller_report(month,recipient='',brand_id=None):
    with reading() as c:r=filtered_report(report_data(c,month),brand_id)
    data=seller_rows_from_month(r)
    if recipient:data=[v for v in data if norm(v['recipient'])==norm(recipient)]
    grouped={}
    for row in data:
        key=norm(row['recipient']);a=grouped.setdefault(key,{'name':row['recipient'],'units':0,'documents':set(),'pending':set()})
        if row['status']=='VIGENTE':
            a['units']+=row['effective'];a['documents'].add(row['number'])
            if row['signature']=='Pendiente de adjuntar':a['pending'].add(row['number'])
    summary=[{'name':v['name'],'units':v['units'],'documents':len(v['documents']),'pending':len(v['pending'])} for v in grouped.values()]
    summary.sort(key=lambda x:(-x['units'],x['name']))
    return {'month':month,'start':r['start'],'end':r['end'],'scope':r['scope'],'recipient':recipient,
        'rows':data,'summary':summary,'units':sum(v['effective'] for v in data),
        'documents':len({v['number'] for v in data if v['status']=='VIGENTE'}),
        'note':'Solo entregas directas a asesores. Anuladas al corte no suman. Eventos y préstamos permanecen en su reporte. Adjunto no equivale a firma verificada; se informa el estado actual del respaldo.'}


def add_seller_sheets(w,data,month,scope):
    head=w.add_format({'bold':True,'bg_color':'#6F161C','font_color':'#FFFFFF','text_wrap':True,'valign':'vcenter'})
    title=w.add_format({'bold':True,'font_size':18,'font_color':'#27232A'})
    note=w.add_format({'font_size':10,'font_color':'#786E75','text_wrap':True})
    textfmt=w.add_format({'text_wrap':True,'valign':'top','font_size':10})
    qtyfmt=w.add_format({'num_format':'#,##0','font_size':10})
    summary=w.add_worksheet('Resumen asesores');summary.hide_gridlines(2);summary.freeze_panes(5,1)
    summary.merge_range('A1:E2','ENTREGAS A ASESORES · '+month,title)
    summary.merge_range('A3:E3',scope+' · Anuladas no suman. Los adjuntos requieren revisión de firma.',note)
    summary.write_row(4,0,['Asesor','Fichas vigentes','Unidades entregadas','Fichas sin adjunto','Observación'],head)
    summary.set_row(4,32);summary.set_column('A:A',31);summary.set_column('B:D',20,qtyfmt);summary.set_column('E:E',42,textfmt)
    detail=w.add_worksheet('Detalle asesores');detail.hide_gridlines(2);detail.freeze_panes(1,4)
    detail.write_row(0,0,['Fecha','Ficha','Asesor','Marca / proveedor','Código','Artículo','Cantidad ficha','Estado','Unidades válidas','Respaldo firmado','Registrado por','Observaciones'],head)
    detail.set_row(0,32);detail.set_column('A:B',15);detail.set_column('C:D',26,textfmt);detail.set_column('E:E',14);detail.set_column('F:F',40,textfmt);detail.set_column('G:I',18,qtyfmt);detail.set_column('J:L',33,textfmt)
    group={};articles={};display_names={}
    for i,x in enumerate(data,1):
        x={**x,'recipient':display_names.setdefault(norm(x['recipient']),x['recipient'])}
        values=[x['day'],x['number'],x['recipient'],x['brand'],x['code'],x['name'],x['quantity'],x['status']]
        detail.write_row(i,0,values,textfmt);detail.write_formula(i,8,f'=IF(H{i+1}="VIGENTE",G{i+1},0)',qtyfmt,x['effective'])
        detail.write_row(i,9,[x['signature'],x['operator'],x['note']],textfmt);detail.set_row(i,32)
        a=group.setdefault(x['recipient'],{'docs':set(),'pending':set(),'units':0})
        if x['status']=='VIGENTE':
            a['docs'].add(x['number']);a['units']+=x['effective']
            if x['signature']=='Pendiente de adjuntar':a['pending'].add(x['number'])
            key=(x['recipient'],x['brand'],x['code'],x['name']);articles[key]=articles.get(key,0)+x['effective']
    if data:detail.autofilter(0,0,len(data),11)
    for i,(name,v) in enumerate(sorted(group.items()),5):
        summary.write(i,0,name,textfmt);summary.write_number(i,1,len(v['docs']),qtyfmt)
        last=max(2,len(data)+1)
        summary.write_formula(i,2,f'=SUMIF(\'Detalle asesores\'!C2:C{last},A{i+1},\'Detalle asesores\'!I2:I{last})',qtyfmt,v['units'])
        summary.write_number(i,3,len(v['pending']),qtyfmt);summary.write(i,4,'Revisar físicamente las firmas de los adjuntos.',note)
    if not data:summary.merge_range('A6:E7','No hay entregas a asesores en este período y filtro.',note)
    elif group:
        chart=w.add_chart({'type':'bar'})
        chart.add_series({'name':'Unidades entregadas','categories':['Resumen asesores',5,0,4+len(group),0],
            'values':['Resumen asesores',5,2,4+len(group),2],'fill':{'color':'#8556A6'},'border':{'none':True}})
        chart.set_legend({'none':True});chart.set_size({'width':760,'height':300});summary.insert_chart(7+len(group),0,chart)
    ar=w.add_worksheet('Artículos por asesor');ar.hide_gridlines(2);ar.freeze_panes(1,1)
    ar.write_row(0,0,['Asesor','Marca / proveedor','Código','Artículo','Total entregado'],head)
    ar.set_column('A:B',28,textfmt);ar.set_column('C:C',15);ar.set_column('D:D',44,textfmt);ar.set_column('E:E',20,qtyfmt)
    for i,(key,value) in enumerate(sorted(articles.items()),1):ar.write_row(i,0,[*key,value],textfmt);ar.set_row(i,28)
    return summary


def seller_xlsx(r):
    import xlsxwriter
    out=io.BytesIO();w=xlsxwriter.Workbook(out,{'in_memory':True,'strings_to_formulas':False,'strings_to_urls':False})
    tab=add_seller_sheets(w,r['rows'],r['month'],r['scope']+(' · '+r['recipient'] if r['recipient'] else ''))
    tab.activate();w.close();return out.getvalue()


def seller_pdf(r):
    e=pdf_setup();P=e['Paragraph'];T=e['Table'];S=e['Spacer'];styles=e['styles'];C=e['colors']
    out=io.BytesIO();doc=e['SimpleDocTemplate'](out,pagesize=e['landscape'](e['A4']),leftMargin=34,rightMargin=34,topMargin=30,bottomMargin=40,
        title='Entregas a asesores '+r['month'],author='Makropetrol')
    story=pdf_logo(get_logo(),e['Image'])+[S(1,12),P('ENTREGAS A ASESORES',styles['MPTitle']),
        P(html.escape(r['scope']+' · '+r['month']+(' · '+r['recipient'] if r['recipient'] else '')),styles['MPSub']),
        P(f"<b>{r['units']:,}</b> unidades · <b>{r['documents']}</b> fichas vigentes · Corte {r['end']}",styles['MPNote']),S(1,12),P(html.escape(r['note']),styles['MPSub'])]
    head=['Asesor','Fichas vigentes','Unidades','Fichas sin adjunto']
    data=[[P(x,styles['MPHead']) for x in head]]
    for x in r['summary']:data.append([P(html.escape(str(x[k])),styles['MPCell']) for k in ('name','documents','units','pending')])
    if len(data)==1:data.append([P('Sin entregas registradas',styles['MPCell']),'0','0','0'])
    table=T(data,colWidths=[390,120,120,140],repeatRows=1);table.setStyle(e['TableStyle'](pdf_table_style(C)));story.append(table)
    if r['rows']:
        story.extend([e['PageBreak'](),P('DETALLE DE LAS ENTREGAS',styles['MPTitle'])])
        data=[[P(x,styles['MPHead']) for x in ['Fecha / ficha','Asesor','Marca / artículo','Cantidad','Estado / respaldo']]]
        for x in r['rows']:
            vals=[x['day']+'\n'+x['number'],x['recipient'],x['brand']+' · '+x['code']+'\n'+x['name'],x['quantity'],x['status']+'\n'+x['signature']]
            data.append([P(html.escape(str(v)).replace('\n','<br/>'),styles['MPCell']) for v in vals])
        table=T(data,colWidths=[95,140,300,55,180],repeatRows=1);table.setStyle(e['TableStyle'](pdf_table_style(C)));story.append(table)
    doc.build(story,onFirstPage=footer,onLaterPages=footer);return out.getvalue()


def _dispatch_original(request):
    rid=str(request.get('id',''))
    if not re.fullmatch(r'[a-zA-Z0-9-]{12,80}',rid):
        return {'id':rid,'status':400,'body':{'error':'Identificador de solicitud inválido.'}}
    def result(body,status=200,mime='application/json; charset=utf-8',filename=None):
        headers={'Content-Type':mime,'Cache-Control':'no-store'}
        if filename:
            safe=re.sub(r'[^A-Za-z0-9_.-]','_',filename)
            headers['Content-Disposition']=f'attachment; filename="{safe}"'
        if isinstance(body,(bytes,bytearray,memoryview)):
            return {'id':rid,'status':status,'headers':headers,'encoding':'base64','body':base64.b64encode(body).decode()}
        return {'id':rid,'status':status,'headers':headers,'body':body}
    try:
        raw_path=str(request.get('path',''))
        if len(raw_path)>2048: raise AppError('Ruta demasiado larga.')
        url=urlparse(raw_path)
        if url.scheme or url.netloc: raise AppError('Ruta no permitida.')
        path=url.path
        q={k:v[0] for k,v in parse_qs(url.query).items()}
        method=request.get('method','GET')
        if method=='POST':
            data=request.get('data')
            if path not in POST_ROUTES: return result({'error':'Acción no disponible.'},404)
            if not isinstance(data,dict): raise AppError('Solicitud inválida.')
            if len(json.dumps(data))>MAX_UPLOAD*2: raise AppError('El archivo supera el tamaño permitido.')
            with LOCK:
                with reading() as c:
                    if data.get('_storage_epoch') != meta(c,'storage_epoch'):
                        raise AppError('El almacén se restauró o reinició. Pulsa Actualizar y revisa el inventario antes de registrar otra ficha.')
                return result(POST_ROUTES[path](data))
        if method!='GET': raise AppError('Método no permitido.')
        if path=='/api/catalog-csv':return result(catalog_csv(),mime='text/csv; charset=utf-8',filename='Revision_catalogo_marcas.csv')
        if path=='/api/state': return result(snapshot())
        if path=='/api/document': return result(document_data(integer(q.get('id'))))
        if path=='/api/receipt':
            doc=document_data(integer(q.get('id')))
            return result(receipt_pdf(doc),mime='application/pdf',filename=doc['number']+'.pdf')
        if path in ('/api/report','/api/report-file'):
            with reading() as c:r=filtered_report(report_data(c,q.get('month','')),q.get('brand'))
            if path=='/api/report': return result(r)
            name=re.sub('[^A-Za-z0-9_-]','_',r['scope'])+'_'+r['month']
            if q.get('format')=='pdf': return result(monthly_pdf(r),mime='application/pdf',filename=name+'.pdf')
            return result(xlsx_report(r),mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',filename=name+'.xlsx')
        if path=='/api/all-reports':
            return result(all_reports_zip(q.get('month','')),mime='application/zip',filename='Reportes_marketing_'+q.get('month','')+'.zip')
        if path=='/api/template':
            return result(excel_template(q.get('mode','movement')),mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',filename='Plantilla_marketing.xlsx')
        if path=='/api/backup': return result(backup_zip(),mime='application/zip',filename='Respaldo_marketing_'+today().isoformat()+'.zip')
        if path=='/api/attachment':
            with reading() as c:
                r=c.execute('SELECT name,mime,data FROM attachments WHERE id=?',(integer(q.get('id')),)).fetchone()
            if not r: raise AppError('Adjunto no encontrado.')
            return result(r['data'],mime=r['mime'],filename=r['name'])
        return result({'error':'Ruta no encontrada.'},404)
    except AppError as exc:
        return result({'error':str(exc)},400)
    except ImportError:
        return result({'error':'Falta una dependencia. Revisa requirements.txt y los registros de Streamlit.'},500)
    except Exception as exc:
        # No devolver datos de conexión, credenciales, SQL ni fichas al navegador/log.
        logger.error('Acción fallida (%s); solicitud %s',type(exc).__name__,rid)
        return result({'error':'No se pudo completar la operación. Consulta Movimientos antes de repetir una entrega y revisa los registros de Streamlit. No borres datos_marketing.'},503)



