def dispatch(request):
    """Extra routes plus the original validated command router."""
    rid=str(request.get('id',''));token=None
    try:
        if not re.fullmatch(r'[a-zA-Z0-9-]{12,80}',rid):raise AppError('Identificador de solicitud inválido.')
        raw=str(request.get('path',''))
        if len(raw)>2048:raise AppError('Ruta demasiado larga.')
        url=urlparse(raw)
        if url.scheme or url.netloc:raise AppError('Ruta no permitida.')
        q={k:v[0] for k,v in parse_qs(url.query).items()};method=request.get('method','GET')
        if method=='POST':
            data=request.get('data')
            if not isinstance(data,dict):raise AppError('Solicitud inválida.')
            token=_EXPECTED_EPOCH.set(data.get('_storage_epoch','missing'))
        if method=='GET' and url.path=='/api/keystone-quantities':
            return {'id':rid,'status':200,'body':keystone_quantity_review()}
        if method=='GET' and url.path=='/api/revision':
            with reading() as c:body={'revision':int(meta(c,'revision','0')),'epoch':meta(c,'storage_epoch')}
            return {'id':rid,'status':200,'body':body}
        if method=='GET' and url.path in ('/api/sellers','/api/sellers-file'):
            r=seller_report(q.get('month',''),q.get('recipient',''),q.get('brand'))
            if url.path=='/api/sellers':return {'id':rid,'status':200,'body':r}
            pdf=q.get('format')=='pdf';blob=seller_pdf(r) if pdf else seller_xlsx(r)
            name='Entregas_asesores_'+r['month']+('.pdf' if pdf else '.xlsx')
            return {'id':rid,'status':200,'encoding':'base64','body':base64.b64encode(blob).decode(),
                'headers':{'Content-Type':'application/pdf' if pdf else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                    'Content-Disposition':f'attachment; filename="{name}"'}}
        return _dispatch_original(request)
    except AppError as exc:return {'id':rid,'status':400,'body':{'error':str(exc)}}
    except Exception as exc:
        logging.getLogger('marketing').error('Solicitud fallida: %s',type(exc).__name__)
        return {'id':rid,'status':503,'body':{'error':'No se pudo completar la acción. Revisa la conexión antes de repetirla.'}}
    finally:
        if token is not None:_EXPECTED_EPOCH.reset(token)


